<?php
if($_SERVER['REQUEST_METHOD']==='POST'){
try{verify_csrf();if(!admin())throw new RuntimeException('Acesso restrito.');$nome=trim($_POST['nome']??'');$pat=filter_var($_POST['patrimonio']??'',FILTER_VALIDATE_INT);$cat=filter_var($_POST['categoria_id']??'',FILTER_VALIDATE_INT);$desc=trim($_POST['descricao']??'');if(!$nome||!$pat||!$cat)throw new RuntimeException('Preencha nome, patrimônio e categoria.');$s=$conn->prepare('INSERT INTO equipamentos(nome,patrimonio,categoria_id,descricao) VALUES(?,?,?,?)');$s->bind_param('siis',$nome,$pat,$cat,$desc);$s->execute();flash('Equipamento cadastrado.');}catch(Throwable $e){flash('Erro: '.$e->getMessage());}go('equipamentos');}
$cats=$conn->query('SELECT id,nome FROM categorias ORDER BY nome');
$rows=$conn->query('SELECT e.id,e.nome,e.patrimonio,e.status,c.nome AS categoria FROM equipamentos e INNER JOIN categorias c ON c.id=e.categoria_id ORDER BY e.nome');
?><h1>Equipamentos</h1><?php if(admin()):?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Nome<input name="nome" required></label><label>Patrimônio<input name="patrimonio" type="number" min="1" required></label><label>Categoria<select name="categoria_id" required><option value="">Selecione</option><?php while($c=$cats->fetch_assoc()):?><option value="<?=$c['id']?>"><?=h($c['nome'])?></option><?php endwhile;?></select></label><label>Descrição<input name="descricao"></label><button>Cadastrar equipamento</button></form><?php endif;?><table><tr><th>Nome</th><th>Patrimônio</th><th>Categoria</th><th>Status</th></tr><?php while($r=$rows->fetch_assoc()):?><tr><td><?=h($r['nome'])?></td><td><?=h($r['patrimonio'])?></td><td><?=h($r['categoria'])?></td><td><?=h($r['status'])?></td></tr><?php endwhile;?></table>
